class Solution {
public:
    int edgeScore(std::vector<int>& edges) {
        int n = edges.size();
        std::vector<long long> scores(n, 0);
        for (int i = 0; i < n; ++i) {
            scores[edges[i]] += i;
        }
        int best_node = 0;
        long long max_score = -1;
        for (int i = 0; i < n; ++i) {
            if (scores[i] > max_score) {
                max_score = scores[i];
                best_node = i;
            }
        }
        return best_node;
    }
};

class Solution {
    public int edgeScore(int[] edges) {
        int n = edges.length;
        long[] scores = new long[n];
        for (int i = 0; i < n; ++i) {
            scores[edges[i]] += i;
        }
        int bestNode = 0;
        long maxScore = -1;
        for (int i = 0; i < n; ++i) {
            if (scores[i] > maxScore) {
                maxScore = scores[i];
                bestNode = i;
            }
        }
        return bestNode;
    }
}

